def _interpolate(raw: dict[str, dict[str, str]]) -> dict[str, dict[str, str]]:
    done: dict[tuple[str, str], str] = {}
    active: set[tuple[str, str]] = set()

    def resolve(section: str, key: str) -> str:
        ref = (section, key)
        if ref in done:
            return done[ref]
        if ref in active:
            raise InterpolationError(f"cycle at ${{{section}:{key}}}")
        active.add(ref)
        value, out, i = raw[section][key], [], 0
        while True:
            j = value.find("$", i)
            if j < 0:
                out.append(value[i:])
                break
            out.append(value[i:j])
            end = value.find("}", j + 2) if value.startswith("${", j) else -1
            if value.startswith("$$", j):
                out.append("$")
                i = j + 2
            elif end >= 0:
                other, colon, name = value[j + 2:end].rpartition(":")
                other = other.strip() if colon else section
                name = name.strip().lower()
                if other not in raw:
                    raise InterpolationError(f"missing section {other!r} in {value[j:end + 1]}")
                if name not in raw[other]:
                    raise InterpolationError(f"missing key {name!r} in {value[j:end + 1]}")
                out.append(resolve(other, name))
                i = end + 1
            else:
                out.append("$")
                i = j + 1
        active.discard(ref)
        done[ref] = "".join(out)
        return done[ref]

    return {s: {k: resolve(s, k) for k in keys} for s, keys in raw.items()}

